// Stare ID (ramka i kask dzieliły jeden ekwipunek) -> nowe ID ramek
const LEGACY_HELMET_TO_FRAME = {
    'helmet-swieta': 'frame-swieta',
    'helmet-halloween': 'frame-halloween',
    'helmet-retro': 'frame-retro',
    'helmet-zloty': 'frame-zloty'
};

function normalizeFrameId(id) {
    if (!id || id === 'default') return null;
    if (AVATAR_FRAME_DEFS[id]) return id;
    return LEGACY_HELMET_TO_FRAME[id] || null;
}

var _avatarFrameUid = 0;
function avatarFrameSvg(frameId) {
    const def = AVATAR_FRAME_DEFS[frameId];
    if (!def) return '';
    _avatarFrameUid++;
    return def.svg.replace(/__ID__/g, 'af' + _avatarFrameUid);
}

// Nakłada ramkę na <img> awatara (owija go w kontener i dokłada nakładkę SVG).
function setAvatarFrame(imgEl, frameId) {
    if (!imgEl) return;
    const id = normalizeFrameId(frameId);
    let host = (imgEl.parentElement && imgEl.parentElement.classList.contains('avatar-frame-host')) ? imgEl.parentElement : null;

    if (!id) {
        if (host) {
            host.className = 'avatar-frame-host';
            const old = host.querySelector(':scope > .avatar-frame-overlay');
            if (old) old.remove();
        }
        return;
    }

    if (!host) {
        host = document.createElement('span');
        host.className = 'avatar-frame-host';
        if (imgEl.style.width === '100%') { host.style.width = '100%'; host.style.height = '100%'; }
        imgEl.parentNode.insertBefore(host, imgEl);
        host.appendChild(imgEl);
    }

    const def = AVATAR_FRAME_DEFS[id];
    host.className = 'avatar-frame-host ' + def.cls + (def.round ? ' frame-round' : '');
    let overlay = host.querySelector(':scope > .avatar-frame-overlay');
    if (!overlay) {
        overlay = document.createElement('span');
        overlay.className = 'avatar-frame-overlay';
        host.appendChild(overlay);
    }
    overlay.innerHTML = avatarFrameSvg(id);
}

// Podgląd ramki w sklepie
function frameShopPreviewHTML(frameId) {
    const def = AVATAR_FRAME_DEFS[frameId];
    const hostCls = def ? ('avatar-frame-host ' + def.cls + (def.round ? ' frame-round' : '')) : 'avatar-frame-host';
    const overlay = def ? `<span class="avatar-frame-overlay">${avatarFrameSvg(frameId)}</span>` : '';
    return `<div class="shop-frame-preview"><span class="${hostCls}"><span class="shop-frame-preview-avatar">👤</span>${overlay}</span></div>`;
}
